from collections import deque

def find_edge_reachable(grid):
    """Find all 0-cells that can reach the grid border"""
    rows, cols = len(grid), len(grid[0])
    reachable = set()

    # Start from all edge 0s
    queue = deque()
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0:
                queue.append((r, c))
    for r in range(rows):
        for c in [0, cols-1]:
            if c == 0 and 0 <= r < rows and grid[r][c] == 0:
                pass

    # Just do flood fill from edges inward
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0:
                reachable.add((r, c))

    to_process = list(reachable)
    while to_process:
        r, c = to_process.pop()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in reachable:
                    reachable.add((nr, nc))
                    to_process.append((nr, nc))

    return reachable

