def reach_from_corner(grid, corner):
    """BFS from a specific direction"""
    rows, cols = len(grid), len(grid[0])
    reachable = set()

    if corner == 'top':
        q = deque([(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0 and r == 0])
    elif corner == 'bottom':
        q = deque([(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0 and r == rows - 1])
    elif corner == 'left':
        q = deque([(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0 and c == 0])
    elif corner == 'right':
        q = deque([(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0 and c == cols - 1])
    else:
        return set()

    while q:
        r, c = q.popleft()
        if (r, c) in reachable:
            continue
        reachable.add((r, c))
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                if (nr, nc) not in reachable:
                    q.append((nr, nc))

    return reachable

